parameters.jsCode:
// One row per onboarding task for this client.
// Edit this list to match how YOU onboard — the rows land in the
// Onboarding Tracker sheet, all starting at 'To do'.
const client = $('Normalise Client').first().json;
const tasks = [
  'Kickoff call scheduled',
  'Signed agreement filed + first invoice sent',
  'Client assets received (logo, brand files, photos)',
  'Access received the safe way (invites, not passwords)',
  'Client folder shared with the client',
  'First deliverable date confirmed with client',
  'Internal brief written for the team'
];
return tasks.map(task => ({ json: {
  client: client.business_name,
  contact_name: client.client_name,
  contact_email: client.email,
  package: client.service_package,
  task: task,
  status: 'To do',
  created: new Date().toISOString().slice(0, 10)
}}));

